请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-004

=== 用户原始指令 (query.txt) ===
整个低电提醒的,字在背景图上,能进系统设置,看日程,快没电喊我

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个低电提醒的,字在背景图上,能进系统设置,看日程,快没电喊我",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "power": {
        "title": "低电提醒",
        "levelText": "电量 12%",
        "statusText": "快没电时喊我",
        "actionText": "开启省电"
      },
      "data": {
        "calendar": {
          "summary": "下一程 18:30",
          "items": [
            {
              "entityName": "calendar",
              "entityId": "mock-calendar-low-power-004",
              "title": "晚间日程",
              "dtStart": "18:30",
              "dtEnd": "19:00",
              "eventLocation": "手机日历"
            }
          ]
        }
      },
      "assets": {
        "powerIcon": "resources/base/media/icon_save_power.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "power_icon",
      "src": "resources/base/media/icon_save_power.png",
      "use": "low power icon",
      "description": "省电模式图标，适合低电提醒和省电开关场景。",
      "bindTo": "/assets/powerIcon",
      "static": true
    }
  ]
}

